    this.mappings.ArrowUp = new Key('ArrowUp', this.ACTION_LINK_MOVE_NORTH, !Key.BLOCKING_ACTION, Key.ENABLED)
    this.mappings.ArrowRight = new Key('ArrowRight', this.ACTION_LINK_MOVE_EAST, !Key.BLOCKING_ACTION, Key.ENABLED)
    this.mappings.ArrowDown = new Key('ArrowDown', this.ACTION_LINK_MOVE_SOUTH, !Key.BLOCKING_ACTION, Key.ENABLED)
    this.mappings.KeyA = new Key('KeyA', this.ACTION_LINK_USE_ITEM_A, Key.BLOCKING_ACTION, !Key.ENABLED)
    this.mappings.KeyB = new Key('KeyB', this.ACTION_LINK_USE_ITEM_B, Key.BLOCKING_ACTION, !Key.ENABLED)
