'use strict'

import soundManager from '../service/sound-manager'
import clock from '../service/clock'
import hitboxManager from '../service/hitbox-manager'
import resource from '../resource'
import { UNIQUE_ITEMS, LINK_ACTION_MOVE, SOUND_FANFARE, LINK_ACTION_PICK, SOUND_TEXT_LOOP, SOUND_OVERWORLD, DIRECTION_EAST, DIRECTION_WEST, TRANSITION_MAP_INCREMENT_DELTA, DIRECTION_SOUTH, SOUND_STAIRS, TILE_HEIGHT, TRANSITION_MAP_INTERVAL_PLAY, DIRECTION_NORTH } from '../constant'

class CaveEntrance {
  async play (link) {
    return new Promise((resolve) => {
      link.y += TILE_HEIGHT
      const limitY = link.y - 3 * TILE_HEIGHT
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        link.y -= 2
        if (link.y <= limitY) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, 15)
    })
  }
}

class CaveExit {
  async play (link, currentMap) {
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        link.y += 2
        if (link.y > currentMap.y + currentMap.height) {
          transitionTimer.cancel()
          link.stopWalking()
          resolve()
        }
      }, 15)
    })
  }
}

class CaveStairsDown {
  async play (link) {
    return new Promise((resolve) => {
      soundManager.stop(resource.getSound(SOUND_OVERWORLD))
      soundManager.play(resource.getSound(SOUND_STAIRS))
      link.direction = DIRECTION_NORTH
      link.x = link.tile.x
      link.y = link.tile.y
      link.clipY = 0
      link.startWalking()
      const transitionTimer = clock.repeat(() => {
        link.clipY++
        if (link.clipY >= TILE_HEIGHT) {
          transitionTimer.cancel()
          link.clipY = 0
          link.stopWalking()
          resolve()
        }
      }, 30)
    })
  }
}

class CaveStairsUp {
  async play (link) {
    return new Promise((resolve) => {
      soundManager.play(resource.getSound(SOUND_STAIRS))
      link.direction = DIRECTION_SOUTH
      link.clipY = TILE_HEIGHT
      link.startWalking()
      const transitionTimer = clock.repeat(() => {
        link.clipY--
        if (link.clipY <= 0) {
          transitionTimer.cancel()
          link.clipY = 0
          link.stopWalking()
          soundManager.play(resource.getSound(SOUND_OVERWORLD))
          resolve()
        }
      }, 30)
    })
  }
}

class MapDrag {
  async play (link, currentMap, targetMap) {
    if (link.direction === DIRECTION_EAST) {
      return this.playEast(link, currentMap, targetMap)
    }
    if (link.direction === DIRECTION_NORTH) {
      return this.playNorth(link, currentMap, targetMap)
    }
    if (link.direction === DIRECTION_SOUTH) {
      return this.playSouth(link, currentMap, targetMap)
    }
    if (link.direction === DIRECTION_WEST) {
      return this.playWest(link, currentMap, targetMap)
    }
  }

  playEast (link, currentMap, targetMap) {
    currentMap.offsetX = 0
    targetMap.offsetX = 0
    link.x = currentMap.x + currentMap.width - link.width

    const nbTicks = Math.round(targetMap.width / TRANSITION_MAP_INCREMENT_DELTA)
    const linkIncrementDelta = (targetMap.width - link.width) / nbTicks

    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        currentMap.offsetX -= TRANSITION_MAP_INCREMENT_DELTA
        targetMap.offsetX -= TRANSITION_MAP_INCREMENT_DELTA
        link.x -= linkIncrementDelta
        if (currentMap.offsetX < -currentMap.width && targetMap.offsetX < -targetMap.width) {
          transitionTimer.cancel()

          targetMap.offsetX = 0
          link.stopWalking()
          link.x = targetMap.x
          currentMap.offsetX = 0

          resolve()
        }
      }, TRANSITION_MAP_INTERVAL_PLAY)
    })
  }

  playNorth (link, currentMap, targetMap) {
    currentMap.offsetY = 0
    targetMap.offsetY = 0
    link.y = currentMap.y

    const nbTicks = Math.round(targetMap.height / TRANSITION_MAP_INCREMENT_DELTA)
    const linkIncrementDelta = (targetMap.height - link.height) / nbTicks

    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        currentMap.offsetY += TRANSITION_MAP_INCREMENT_DELTA
        targetMap.offsetY += TRANSITION_MAP_INCREMENT_DELTA
        link.y += linkIncrementDelta
        if (currentMap.offsetY > currentMap.height && targetMap.offsetY > targetMap.height) {
          transitionTimer.cancel()

          targetMap.offsetY = 0
          link.stopWalking()
          link.y = targetMap.y + targetMap.height - link.height
          currentMap.offsetY = 0

          resolve()
        }
      }, TRANSITION_MAP_INTERVAL_PLAY)
    })
  }

  playSouth (link, currentMap, targetMap) {
    currentMap.offsetY = 0
    targetMap.offsetY = 0
    link.y = currentMap.y + currentMap.height - link.height

    const nbTicks = Math.round(targetMap.height / TRANSITION_MAP_INCREMENT_DELTA)
    const linkIncrementDelta = (targetMap.height - link.height) / nbTicks

    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        currentMap.offsetY -= TRANSITION_MAP_INCREMENT_DELTA
        targetMap.offsetY -= TRANSITION_MAP_INCREMENT_DELTA
        link.y -= linkIncrementDelta
        if (currentMap.offsetY < -currentMap.height && targetMap.offsetY < -targetMap.height) {
          transitionTimer.cancel()

          targetMap.offsetY = 0
          link.stopWalking()
          link.y = targetMap.y
          currentMap.offsetY = 0

          resolve()
        }
      }, TRANSITION_MAP_INTERVAL_PLAY)
    })
  }

  playWest (link, currentMap, targetMap) {
    currentMap.offsetX = 0
    targetMap.offsetX = 0
    link.x = currentMap.x

    const nbTicks = Math.round(targetMap.width / TRANSITION_MAP_INCREMENT_DELTA)
    const linkIncrementDelta = (targetMap.width - link.width) / nbTicks

    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        link.startWalking()
        currentMap.offsetX += TRANSITION_MAP_INCREMENT_DELTA
        targetMap.offsetX += TRANSITION_MAP_INCREMENT_DELTA
        link.x += linkIncrementDelta
        if (currentMap.offsetX > currentMap.width && targetMap.offsetX > targetMap.width) {
          transitionTimer.cancel()

          targetMap.offsetX = 0
          link.stopWalking()
          link.x = targetMap.x + targetMap.width - link.width
          currentMap.offsetX = 0

          resolve()
        }
      }, TRANSITION_MAP_INTERVAL_PLAY)
    })
  }
}

class ItemPick {
  buy (link, item) {
    let i = item.price ?? 0
    const soundTimer = clock.repeat(() => {
      // soundManager.play(resource.getSound(SOUND_GET_RUPEE))
    }, 200)
    const buyTimer = clock.repeat(() => {
      i--
      link.inventory.rupees--
      if (i === 0) {
        buyTimer.cancel()
        soundTimer.cancel()
        if (link.inventory.rupees < 0) {
          link.inventory.rupee = 0
        }
      }
    }, 25)
  }

  removeItemFromMap (map, item) {
    const index = map.items.indexOf(item)
    if (index > -1) {
      map.items.splice(index, 1)
    }
  }

  addItemToMap (map, item) {
    map.items.push(item)
  }

  play (link, item) {
    if (item.price) {
      this.buy(link, item)
    }

    if (link.map.character) {
      link.map.character.vanish(1300)
    }

    const clonedItem = item.clone()
    clonedItem.price = undefined
    for (const i of link.map.items) {
      i.enabled = false
    }

    // Test picking item or not
    /* if (false) {
      this.finalizeTransition(link.map, item)
      return
    } */

    link.stopWalking()
    link.action = LINK_ACTION_PICK
    this.addItemToMap(link.map, clonedItem)

    const itemCenterX = hitboxManager.getHorizontalCenter(clonedItem.hitbox)
    const itemDeltaX = itemCenterX - clonedItem.x
    clonedItem.x = link.x - itemDeltaX + 4
    clonedItem.y = link.y - clonedItem.height
    soundManager.play(resource.getSound(SOUND_FANFARE))

    const self = this
    return new Promise((resolve) => {
      clock.delay(() => {
        link.action = LINK_ACTION_MOVE
        self.removeItemFromMap(link.map, clonedItem)
        self.finalizeTransition(link.map, item)
        resolve()
      }, 1300)
    })
  }

  finalizeTransition (map, item) {
    if (UNIQUE_ITEMS.includes(item.name)) {
      map.items = []
      map.characters = []
    }
  }
}

class Dialog {
  async play (link) {
    let length = 0
    soundManager.play(resource.getSound(SOUND_TEXT_LOOP))
    return new Promise((resolve) => {
      const transitionTimer = clock.repeat(() => {
        length++
        link.map.character.displayedText = link.map.character.text.substring(0, length)
        if (link.map.character.displayedText === link.map.character.text) {
          soundManager.stop(resource.getSound(SOUND_TEXT_LOOP))
          transitionTimer.cancel()
          resolve()
        }
      }, 50)
    })
  }
}

export { CaveEntrance, CaveExit, CaveStairsDown, CaveStairsUp, MapDrag, Dialog, ItemPick }
